# Vector floor data for УЛК, in each scan's own pixel coordinates (2600 px wide).
# room tuple: (label, x0, x1, y0, y1, kind='room', aliases=())
# kinds: room | wc | svc (blank) | area (grey, named, not searchable) | place (grey, named, searchable)
F={}
def R(l,x0,x1,y0,y1,k='room',al=()): return (l,x0,x1,y0,y1,k,tuple(al))
def row(y0,y1,items,pre=''):
    out=[]
    for it in items:
        l,x0,x1=it[0],it[1],it[2]; k=it[3] if len(it)>3 else ('svc' if l is None else 'room')
        if k=='room' and l and pre: l=pre+l
        out.append(R(l,x0,x1,y0,y1,k))
    return out
def rect(x0,y0,x1,y1): return f"M{x0} {y0}H{x1}V{y1}H{x0}Z"

# ---------- typical floors 5–11 share the band layout ----------
def typical(f,U,C,L,up,lo,tall,cores,st,band,pre='',extra=()):
    rooms=row(U[0],U[1],up,pre)+row(L[0],L[1],lo,pre)
    for t in tall:
        l,x0,x1,y0,y1=t[:5]; k=t[5] if len(t)>5 else 'room'
        if k=='room' and l and pre: l=pre+l
        rooms.append(R(l,x0,x1,y0,y1,k))
    rooms+=list(extra)
    F[f]=dict(out=[rect(*band)]+[rect(*c) for c in cores],corr=[(band[0]+8,C[0],band[2]-8,C[1])],rooms=rooms,deco=cores,st=st,ent=[],lab=[])

