def t6(f,y,pre,up,lo,tall,extra=()):
    # y = top of band; floors 6–11 bands are 200 px tall with the same grid
    U=(y+17,y+110); C=(y+110,y+134); L=(y+134,y+200)
    cores=[(450,y-50,533,y+8),(758,y-140,833,y+60),(875,y-140,950,y+60),(1333,y-40,1408,y+8),(1817,y-140,1892,y+60),(1925,y-140,1992,y+60),(2200,y-50,2285,y+8)]
